const STY = (bg) => `position:absolute;width:800px;left:70px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.5);background:${bg};color:#0b1020;font-family:inherit;font-weight:800;opacity:0;`;
const G1 = `linear-gradient(180deg,color-mix(in srgb,var(--acc) 72%,#fff),var(--acc) 55%,color-mix(in srgb,var(--acc) 84%,#000))`;
const G2 = `linear-gradient(180deg,color-mix(in srgb,var(--acc2) 72%,#fff),var(--acc2) 55%,color-mix(in srgb,var(--acc2) 84%,#000))`;

root.innerHTML = `
  <div id="c0" style="${STY(G1)}top:80px;height:160px;font-size:52px;">COMPLEX PROMPT</div>
  <svg style="position:absolute;top:0;left:0;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:8;stroke-linecap:round;opacity:0.3">
    <path id="l0" d="M470 240 L210 480" />
    <path id="l1" d="M470 240 L470 480" />
    <path id="l2" d="M470 240 L730 480" />
  </svg>
  <div id="sub0" style="${STY(G2)}top:480px;left:40px;width:270px;height:140px;font-size:38px;">SUB-QUERY</div>
  <div id="sub1" style="${STY(G1)}top:480px;left:335px;width:270px;height:140px;font-size:38px;">SUB-QUERY</div>
  <div id="sub2" style="${STY(G2)}top:480px;left:630px;width:270px;height:140px;font-size:38px;">SUB-QUERY</div>
  <div id="txt" style="position:absolute;top:740px;width:940px;text-align:center;color:#ffffff;font-size:54px;font-weight:900;opacity:0;letter-spacing:-1px;">FAN-OUT TECHNIQUE</div>
  <div id="ans" style="position:absolute;top:840px;width:940px;text-align:center;color:var(--acc2);font-size:44px;font-weight:800;opacity:0;">BETTER ANSWERS</div>
`;

const main = root.querySelector('#c0');
const subs = [0, 1, 2].map(i => root.querySelector('#sub' + i));
const lines = [0, 1, 2].map(i => {
  const el = root.querySelector('#l' + i);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});
const txt = root.querySelector('#txt');
const ans = root.querySelector('#ans');

function frame(t, p, d) {
  const s0 = spr(t, 0.2, 0.8, 5);
  main.style.opacity = s0;
  main.style.transform = `translateY(${lerp(40, 0, s0)}px) scale(${lerp(0.8, 1, s0)})`;

  lines.forEach((l, i) => {
    const ls = spr(t, 0.6 + i * 0.1, 0.9, 6);
    l.el.style.strokeDashoffset = l.len * (1 - ls);
    l.el.style.opacity = ls * 0.3;
  });

  subs.forEach((el, i) => {
    const ss = spr(t, 1.2 + i * 0.15, 0.8, 5);
    el.style.opacity = ss;
    el.style.transform = `translateY(${lerp(30, 0, ss)}px) scale(${lerp(0.9, 1, ss)})`;
  });

  const ts = spr(t, 2.2, 0.8, 4);
  txt.style.opacity = ts;
  txt.style.transform = `translateY(${lerp(20, 0, ts)}px)`;

  const as = spr(t, 2.6, 0.8, 4);
  ans.style.opacity = as;
  ans.style.transform = `translateY(${lerp(15, 0, as)}px)`;

  if (p > 0.55) {
    // Final lock
    main.style.opacity = 1; main.style.transform = 'none';
    subs.forEach(el => { el.style.opacity = 1; el.style.transform = 'none'; });
    lines.forEach(l => { l.el.style.strokeDashoffset = 0; l.el.style.opacity = 0.3; });
    txt.style.opacity = 1; txt.style.transform = 'none';
    ans.style.opacity = 1; ans.style.transform = 'none';
  }
}
